import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{B as i,c as e,f as r,q as a,D as l,Q as o,g as p}from"./chunks/runtime-core.esm-bundler.BPXnTuTE.js";const d="/assets/cron-cover.7mdE4rRR.jpg",_=JSON.parse('{"title":"Linux 定时任务：cron 与 crontab 全面指南","description":"","frontmatter":{},"headers":[],"relativePath":"column/Linux/系统管理/定时任务（cron）.md","filePath":"column/Linux/系统管理/定时任务（cron）.md","lastUpdated":1787968750000}'),c={name:"column/Linux/系统管理/定时任务（cron）.md"};function h(b,s,k,g,u,m){const n=i("ArticleMetadata");return r(),e("div",null,[s[0]||(s[0]=a("h1",{id:"linux-定时任务-cron-与-crontab-全面指南",tabindex:"-1"},[p("Linux 定时任务：cron 与 crontab 全面指南 "),a("a",{class:"header-anchor",href:"#linux-定时任务-cron-与-crontab-全面指南","aria-label":'Permalink to "Linux 定时任务：cron 与 crontab 全面指南"'},"​")],-1)),l(n),s[1]||(s[1]=o('<nav class="table-of-contents"><ul><li><a href="#_1-什么是-cron-与-crontab">1. 什么是 cron 与 crontab？</a></li><li><a href="#_2-crontab-核心管理命令">2. crontab 核心管理命令</a></li><li><a href="#_3-crontab-语法规则-5-颗星表达式">3. crontab 语法规则（5 颗星表达式）</a><ul><li><a href="#常用特殊符号">常用特殊符号</a></li></ul></li><li><a href="#_4-高频实用案例解析">4. 高频实用案例解析</a></li><li><a href="#_5-生产环境坑点与最佳实践">5. 生产环境坑点与最佳实践</a><ul><li><a href="#坑点-1-缺少环境变量导致命令未找到">坑点 1：缺少环境变量导致命令未找到</a></li><li><a href="#坑点-2-输出未定向导致垃圾邮件或静默失败">坑点 2：输出未定向导致垃圾邮件或静默失败</a></li></ul></li><li><a href="#_6-实操案例-配置一个自动日志备份任务">6. 实操案例：配置一个自动日志备份任务</a></li><li><a href="#_7-总结">7. 总结</a></li></ul></nav><p><img src="'+d+`" alt="" loading="lazy"></p><p>在 Linux 系统管理与后端开发中，<strong>定时任务（Cron）</strong> 是实现自动化运维的核心机制。无论是定期备份数据库、清理日志文件、拉取定时数据，还是发送系统通知，都离不开它。</p><h2 id="_1-什么是-cron-与-crontab" tabindex="-1">1. 什么是 cron 与 crontab？ <a class="header-anchor" href="#_1-什么是-cron-与-crontab" aria-label="Permalink to &quot;1. 什么是 cron 与 crontab？&quot;">​</a></h2><ul><li><strong><code>crond</code></strong>：Linux 系统后台运行的守护进程（Daemon），每分钟检查一次是否有需要执行的定时任务。</li><li><strong><code>crontab</code></strong>：全称 &quot;cron table&quot;，即定时任务列表文件。我们通过 <code>crontab</code> 命令来管理当前用户的定时任务。</li></ul><h2 id="_2-crontab-核心管理命令" tabindex="-1">2. crontab 核心管理命令 <a class="header-anchor" href="#_2-crontab-核心管理命令" aria-label="Permalink to &quot;2. crontab 核心管理命令&quot;">​</a></h2><p>用户级的定时任务配置保存在 <code>/var/spool/cron/crontab/$USER</code> 中。<strong>切忌直接用文本编辑器修改此文件</strong>，必须使用 <code>crontab</code> 命令操作：</p><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>说明</th></tr></thead><tbody><tr><td><strong><code>crontab -e</code></strong></td><td><strong>编辑当前用户的定时任务</strong></td><td>初次使用会提示选择编辑器（如 nano 或 vim）</td></tr><tr><td><strong><code>crontab -l</code></strong></td><td><strong>列出当前用户的所有定时任务</strong></td><td>查看配置清单</td></tr><tr><td><strong><code>crontab -r</code></strong></td><td><strong>清空当前用户的所有定时任务</strong></td><td>⚠️ <strong>高危操作</strong>！建议先 <code>crontab -l</code> 备份</td></tr><tr><td><code>sudo crontab -u username -e</code></td><td>编辑指定用户的定时任务</td><td>仅 root 管理员权限可用</td></tr></tbody></table><h2 id="_3-crontab-语法规则-5-颗星表达式" tabindex="-1">3. crontab 语法规则（5 颗星表达式） <a class="header-anchor" href="#_3-crontab-语法规则-5-颗星表达式" aria-label="Permalink to &quot;3. crontab 语法规则（5 颗星表达式）&quot;">​</a></h2><p>在 <code>crontab -e</code> 打开的文件中，每一行代表一条定时任务。标准格式如下：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>*   *   *   *   *   command_to_execute</span></span>
<span class="line"><span>│   │   │   │   │</span></span>
<span class="line"><span>│   │   │   │   └─── 星期几 (Day of week: 0 - 6, 0代表周日)</span></span>
<span class="line"><span>│   │   │   └─────── 月份 (Month: 1 - 12)</span></span>
<span class="line"><span>│   │   └─────────── 日期 (Day of month: 1 - 31)</span></span>
<span class="line"><span>│   └─────────────── 小时 (Hour: 0 - 23)</span></span>
<span class="line"><span>└─────────────────── 分钟 (Minute: 0 - 59)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h3 id="常用特殊符号" tabindex="-1">常用特殊符号 <a class="header-anchor" href="#常用特殊符号" aria-label="Permalink to &quot;常用特殊符号&quot;">​</a></h3><table tabindex="0"><thead><tr><th>符号</th><th>含义</th><th>示例与解读</th></tr></thead><tbody><tr><td><strong><code>*</code></strong></td><td>匹配任意值</td><td><code>*</code> 在分钟位置 = 每分钟</td></tr><tr><td><strong><code>,</code></strong></td><td>列出多个值（逗号分隔）</td><td><code>1,15,30</code> 在分钟位置 = 第 1、15、30 分钟时</td></tr><tr><td><strong><code>-</code></strong></td><td>范围区间</td><td><code>1-5</code> 在星期位置 = 周一到周五</td></tr><tr><td><strong><code>/*</code></strong></td><td>间隔频率（步长）</td><td><code>*/15</code> 在分钟位置 = 每隔 15 分钟</td></tr></tbody></table><h2 id="_4-高频实用案例解析" tabindex="-1">4. 高频实用案例解析 <a class="header-anchor" href="#_4-高频实用案例解析" aria-label="Permalink to &quot;4. 高频实用案例解析&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景需求</th><th>Cron 表达式格式</th></tr></thead><tbody><tr><td><strong>每分钟执行一次</strong></td><td><code>* * * * * /path/to/script.sh</code></td></tr><tr><td><strong>每隔 5 分钟执行一次</strong></td><td><code>*/5 * * * * /path/to/script.sh</code></td></tr><tr><td><strong>每天凌晨 2:30 执行</strong></td><td><code>30 2 * * * /path/to/script.sh</code></td></tr><tr><td><strong>每周一早上 8:00 执行</strong></td><td><code>0 8 * * 1 /path/to/script.sh</code></td></tr><tr><td><strong>每个月 1 号凌晨 0:00 执行</strong></td><td><code>0 0 1 * * /path/to/script.sh</code></td></tr><tr><td><strong>工作日（周一至周五）每小时整点执行</strong></td><td><code>0 * * * 1-5 /path/to/script.sh</code></td></tr></tbody></table><h2 id="_5-生产环境坑点与最佳实践" tabindex="-1">5. 生产环境坑点与最佳实践 <a class="header-anchor" href="#_5-生产环境坑点与最佳实践" aria-label="Permalink to &quot;5. 生产环境坑点与最佳实践&quot;">​</a></h2><p>在使用 cron 时，绝大多数“任务没有如期执行”的问题都来自于以下几点：</p><h3 id="坑点-1-缺少环境变量导致命令未找到" tabindex="-1">坑点 1：缺少环境变量导致命令未找到 <a class="header-anchor" href="#坑点-1-缺少环境变量导致命令未找到" aria-label="Permalink to &quot;坑点 1：缺少环境变量导致命令未找到&quot;">​</a></h3><p><code>crond</code> 执行任务时的环境变量（如 <code>PATH</code>）非常干净，通常只包含 <code>/usr/bin:/bin</code>。如果脚本依赖了 <code>/usr/local/bin</code> 或 Node.js/Python 虚拟环境，会因为找不到命令而失败。</p><p><strong>解法</strong>：在脚本内部或 crontab 顶部显示指定环境变量，或<strong>在配置中使用命令的绝对路径</strong>。</p><h3 id="坑点-2-输出未定向导致垃圾邮件或静默失败" tabindex="-1">坑点 2：输出未定向导致垃圾邮件或静默失败 <a class="header-anchor" href="#坑点-2-输出未定向导致垃圾邮件或静默失败" aria-label="Permalink to &quot;坑点 2：输出未定向导致垃圾邮件或静默失败&quot;">​</a></h3><p>cron 会默认将任务的标准输出（stdout）和错误输出（stderr）尝试通过邮件发送给本地用户。如果不处理，可能会挤满 <code>/var/mail</code>。</p><p><strong>解法</strong>：务必重定向输出到日志文件，或直接丢弃：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. 将标准输出与错误输出重定向到自定义日志文件（推荐）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">30</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /home/alex/scripts/backup.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /home/alex/logs/backup.log</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. 如果不需要日志，直接扔进黑洞 /dev/null</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /home/alex/scripts/clean.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/null</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="_6-实操案例-配置一个自动日志备份任务" tabindex="-1">6. 实操案例：配置一个自动日志备份任务 <a class="header-anchor" href="#_6-实操案例-配置一个自动日志备份任务" aria-label="Permalink to &quot;6. 实操案例：配置一个自动日志备份任务&quot;">​</a></h2><p><strong>实操步骤</strong></p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. 打开定时任务编辑器</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">crontab</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. 在文件末尾添加以下两行：</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 设置环境变量，防止路径找不到</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 每天凌晨 3:00 执行日志清理脚本，并将输出记录到 clean.log</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /bin/bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /home/alex/scripts/clean_logs.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /home/alex/logs/clean.log</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. 保存并退出，终端会提示：crontab: installing new crontab</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 4. 确认任务已生效</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">crontab</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><h2 id="_7-总结" tabindex="-1">7. 总结 <a class="header-anchor" href="#_7-总结" aria-label="Permalink to &quot;7. 总结&quot;">​</a></h2><ol><li><strong>基本格式记准</strong>：<strong>分、时、日、月、周</strong> 5 个字段。</li><li><strong>绝对路径最保险</strong>：在 crontab 中执行的脚本和内部调用的命令，尽量写绝对路径（如 <code>/bin/bash</code>、<code>/usr/bin/python3</code>）。</li><li><strong>做好日志重定向</strong>：始终使用 <code>&gt;&gt; log.txt 2&gt;&amp;1</code> 记录输出，方便排查失败原因。</li></ol>`,29))])}const C=t(c,[["render",h]]);export{_ as __pageData,C as default};
